//   list the files in "logs", then for each file read it, and if it fails, log the error
//   and continue. After that, count them and print it.
// Same sentence in, same code out. Change the sentence, not this file.

use std::error::Error;
use std::fs;

pub fn run() -> Result<(), Box<dyn Error>> {
    // list the files in "logs"  [list_dir/read_dir + propagate]
    let paths = fs::read_dir("logs").and_then(|entries| entries.map(|entry| entry.map(|e| e.path())).collect::<Result<Vec<_>, _>>()).map(|paths| paths.into_iter().filter(|p| p.is_file()).collect::<Vec<_>>())?;
    // for each file  [for_each/for_loop]
    let mut texts = Vec::new();
    for path in &paths {
        // read it  [read_file/to_string + handle]
        let contents = match fs::read_to_string(path) {
            Ok(value) => value,
            Err(err) => {
                eprintln!("failed to read {}: {err}", path.display());
                continue;
            }
        };
        texts.push(contents);
    }
    // count them  [count/len]
    let count = texts.len();
    // print it  [print/display]
    println!("{count}");
    Ok(())
}
